<script setup lang="ts">import {ref} from 'vue';import {readUser,clear} from './stores/session';import {useWorkspace} from './hooks/useWorkspace';import {navigation} from './router/navigation';import {ROLES} from './constants/enums';import Login from './pages/Login.vue';import Overview from './pages/Overview.vue';import Datasets from './pages/Datasets.vue';import Criteria from './pages/Criteria.vue';import Judgments from './pages/Judgments.vue';import Results from './pages/Results.vue';import Reviews from './pages/Reviews.vue';import Notice from './components/common/Notice.vue';const user=ref(readUser()),page=ref(location.hash.slice(1)||'overview');const {data,error,loading,refresh}=useWorkspace(user);function go(value:string){page.value=value;location.hash=value;window.scrollTo(0,0)}function logout(){clear();user.value=null};</script><template><Login v-if="!user" @login="user=$event"/><div class="shell" v-else><aside class="side-logbook"><a class="brand" href="#overview" @click="go('overview')"><span>岩</span><div>岩舟航运<small>备选航段比较航册</small></div></a><div class="contents-label">LOGBOOK / 2026</div><nav><button v-for="n in navigation" :key="n.id" :class="{active:page===n.id}" @click="go(n.id)"><i>{{n.code}}</i>{{n.label}}<b>↗</b></button></nav><div class="side-bottom"><span>模拟方案 / 人工判断</span><p>方向明确，<br/>权重有据。</p><small>{{ROLES[user.role]}}</small><button @click="logout">退出航册</button></div></aside><main class="workspace"><div class="topline"><span>YANZHOU / MULTI-CRITERIA PASSAGES</span><span>{{user.email}}</span></div><Notice v-if="error" error>{{error}}<button class="text-button" @click="refresh">重试</button></Notice><p v-if="loading">正在读取比较航册…</p><template v-else><Overview v-if="page==='overview'" :data="data" @go="go"/><Datasets v-else-if="page==='datasets'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh"/><Criteria v-else-if="page==='criteria'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh"/><Judgments v-else-if="page==='judgments'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh" @go="go"/><Results v-else-if="page==='results'" :data="data"/><Reviews v-else :data="data" :can-write="user.role!=='viewer'" :is-admin="user.role==='admin'" :refresh="refresh"/></template><footer>岩舟航运 · 模拟多准则讨论<span>方向 / 一致性 / 敏感性</span></footer></main></div></template>
